using System;
using System.Collections.Generic;
using UnityEngine;

namespace WorkingVehicles
{
    /// <summary>
    /// Drawing of the mod's panels: rounded-corner boxes, rows with values and bars, keys and notices.
    /// Everything is generated by code (no files): a 9-slice rounded texture tinted with GUI.color.
    /// </summary>
    internal static class Ui
    {
        public static readonly Color Accent = new Color(1f, 0.62f, 0.16f);
        public static readonly Color Backdrop = new Color(0.06f, 0.07f, 0.09f, 0.93f);
        public static readonly Color Green = new Color(0.42f, 0.88f, 0.52f);
        public static readonly Color Red = new Color(1f, 0.42f, 0.38f);
        public static readonly Color Yellow = new Color(1f, 0.82f, 0.30f);
        public static readonly Color Gray = new Color(0.66f, 0.70f, 0.76f);
        public static readonly Color White = new Color(0.96f, 0.97f, 1f);

                static GUIStyle est;

        public static float Sc { get { return Mathf.Clamp(Screen.height / 1080f, 0.7f, 2f); } }

        public static void Start()
        {
            if (est == null)
            {
                est = new GUIStyle(GUI.skin.label);
                est.wordWrap = false;
                est.clipping = TextClipping.Overflow;
            }
        }

        static readonly Dictionary<long, Texture2D> cache = new Dictionary<long, Texture2D>();

        static Texture2D Rounded(int w, int h, int rad)
        {
            long key = ((long)w << 24) | ((long)h << 8) | (long)rad;
            Texture2D t;
            if (cache.TryGetValue(key, out t) && t != null) return t;
            if (cache.Count > 200)
            {
                foreach (var kv in cache) if (kv.Value != null) UnityEngine.Object.Destroy(kv.Value);
                cache.Clear();
            }
            t = new Texture2D(w, h, TextureFormat.RGBA32, false);
            var px = new Color[w * h];
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                {
                    float a = 1f;
                    float cx = x + 0.5f < rad ? rad - (x + 0.5f) : (x + 0.5f > w - rad ? (x + 0.5f) - (w - rad) : 0f);
                    float cy = y + 0.5f < rad ? rad - (y + 0.5f) : (y + 0.5f > h - rad ? (y + 0.5f) - (h - rad) : 0f);
                    if (cx > 0f && cy > 0f) a = Mathf.Clamp01(rad - Mathf.Sqrt(cx * cx + cy * cy) + 0.5f);
                    px[y * w + x] = new Color(1f, 1f, 1f, a);
                }
            t.SetPixels(px);
            t.Apply();
            t.filterMode = FilterMode.Bilinear;
            t.wrapMode = TextureWrapMode.Clamp;
            t.hideFlags = HideFlags.DontUnloadUnusedAsset;
            cache[key] = t;
            return t;
        }

        /// <summary>Rounded rectangle of the given color. radius in pixels.</summary>
        public static void Box(Rect r, Color c, float radius)
        {
            int iw = Mathf.RoundToInt(r.width), ih = Mathf.RoundToInt(r.height);
            if (iw < 2 || ih < 2) return;
            float k = Mathf.Min(radius, iw * 0.5f, ih * 0.5f);
            int tw = iw, th = ih;
            float sc = 1f;
            if ((long)iw * ih > 300000L) { sc = 0.5f; tw = Mathf.Max(2, iw / 2); th = Mathf.Max(2, ih / 2); }
            else if (iw > 40 && iw < 700) tw = (iw + 7) / 8 * 8;   // similar widths share a texture (it is stretched a little)
            int rad = Mathf.Max(1, Mathf.RoundToInt(k * sc));
            if (tw != iw && sc == 1f) rad = Mathf.Max(1, Mathf.RoundToInt(k));
            Texture2D t = Rounded(tw, th, Mathf.Min(rad, tw / 2, th / 2));
            Color g0 = GUI.color;
            GUI.color = c;
            GUI.DrawTexture(new Rect(Mathf.Round(r.x), Mathf.Round(r.y), iw, ih), t);
            GUI.color = g0;
        }

        public static void Text(Rect r, string s, float size, Color c, TextAnchor toward, bool bold)
        {
            if (est == null || string.IsNullOrEmpty(s)) return;
            est.fontSize = Mathf.Max(8, Mathf.RoundToInt(size * Sc));
            est.fontStyle = bold ? FontStyle.Bold : FontStyle.Normal;
            est.alignment = toward;
            est.normal.textColor = new Color(0f, 0f, 0f, 0.55f);
            GUI.Label(new Rect(r.x + 1.5f, r.y + 1.5f, r.width, r.height), s, est);
            est.normal.textColor = c;
            GUI.Label(r, s, est);
        }

        static float Width(string s, float size, bool bold)
        {
            // estimate (not measured with Unity): average character width ~0.54 of the font size
            return s.Length * Mathf.Max(8, Mathf.RoundToInt(size * Sc)) * (bold ? 0.58f : 0.54f);
        }

        public static void Bar(Rect r, float frac, Color c)
        {
            Box(r, new Color(1f, 1f, 1f, 0.10f), r.height * 0.5f);
            float w = Mathf.Max(r.height, r.width * Mathf.Clamp01(frac));
            if (frac > 0.003f) Box(new Rect(r.x, r.y, w, r.height), c, r.height * 0.5f);
        }

        /// <summary>Panel with shadow, colored strip on top, title and subtitle. Returns the usable rectangle (below the title).</summary>
        public static Rect Panel(Rect r, string title, string subtitle, Color accent)
        {
            float e = Sc;
            Box(new Rect(r.x - 6f * e, r.y - 2f * e, r.width + 12f * e, r.height + 14f * e), new Color(0f, 0f, 0f, 0.30f), 22f * e);
            Box(r, Backdrop, 18f * e);
            Box(new Rect(r.x + 18f * e, r.y, 64f * e, 5f * e), accent, 3f * e);
            Text(new Rect(r.x + 24f * e, r.y + 14f * e, r.width - 48f, 40f * e), title, 30f, White, TextAnchor.MiddleLeft, true);
            float lowered = 56f * e;
            if (!string.IsNullOrEmpty(subtitle))
            {
                Text(new Rect(r.x + 24f * e, r.y + 50f * e, r.width - 48f, 24f * e), subtitle, 17f, Gray, TextAnchor.MiddleLeft, false);
                lowered = 82f * e;
            }
            return new Rect(r.x + 14f * e, r.y + lowered, r.width - 28f * e, r.height - lowered - 10f * e);
        }

        /// <summary>A menu row: name on the left, value on the right (in a colored box) and, if requested, a bar.</summary>
        public static void Row(Rect r, string names, string value, Color colValue, bool sel, float bar, Color colBar)
        {
            float e = Sc;
            if (sel)
            {
                Box(r, new Color(Accent.r, Accent.g, Accent.b, 0.20f), 12f * e);
                Box(new Rect(r.x + 5f * e, r.y + r.height * 0.22f, 4f * e, r.height * 0.56f), Accent, 2f * e);
            }
            bool withBar = bar >= 0f;
            float heightText = withBar ? r.height * 0.62f : r.height;
            Text(new Rect(r.x + 20f * e, r.y, r.width * 0.55f, heightText), names, 21f, sel ? White : new Color(0.86f, 0.88f, 0.92f), TextAnchor.MiddleLeft, sel);
            if (!string.IsNullOrEmpty(value))
            {
                float aw = Width(value, 17f, true) + 22f * e;
                Rect chip = new Rect(r.xMax - aw - 12f * e, r.y + (heightText - 28f * e) * 0.5f, aw, 28f * e);
                Box(chip, new Color(colValue.r, colValue.g, colValue.b, 0.20f), 14f * e);
                Text(chip, value, 17f, colValue, TextAnchor.MiddleCenter, true);
            }
            if (withBar) Bar(new Rect(r.x + 20f * e, r.y + r.height * 0.70f, r.width - 40f * e, 7f * e), bar, colBar);
        }

        static void Key(ref float x, float y, string t, string action)
        {
            float e = Sc;
            float tw = Mathf.Max(30f * e, Width(t, 16f, true) + 18f * e);
            Rect k = new Rect(x, y, tw, 28f * e);
            Box(new Rect(k.x, k.y + 2f * e, k.width, k.height), new Color(0f, 0f, 0f, 0.5f), 7f * e);
            Box(k, new Color(0.26f, 0.29f, 0.34f), 7f * e);
            Text(k, t, 16f, White, TextAnchor.MiddleCenter, true);
            x += tw + 8f * e;
            float aw = Width(action, 16f, false) + 4f;
            Text(new Rect(x, y, aw, 28f * e), action, 16f, Gray, TextAnchor.MiddleLeft, false);
            x += aw + 20f * e;
        }

        /// <summary>Line of keys at the bottom of the panel: (key, action) pairs.</summary>
        public static void Footer(Rect panel, params string[] pairs)
        {
            float e = Sc;
            float y = panel.yMax - 40f * e;
            Box(new Rect(panel.x + 20f * e, y - 10f * e, panel.width - 40f * e, 1.5f * e), new Color(1f, 1f, 1f, 0.10f), 1f);
            float x = panel.x + 24f * e;
            for (int i = 0; i + 1 < pairs.Length; i += 2) Key(ref x, y, pairs[i], pairs[i + 1]);
        }

        /// <summary>Message in a pill (at the bottom). 'alerta' paints it red.</summary>
        public static void Notice(float W, float H, string text, bool alert)
        {
            Pill(W, H * 0.84f, text, alert ? Red : Accent);
        }

        /// <summary>Hint about what is being looked at; if it starts with [X] it draws that key as a button.</summary>
        public static void Hint(float W, float y, string text)
        {
            Pill(W, y, text, Green);
        }

        static void Pill(float W, float y, string text, Color point)
        {
            if (string.IsNullOrEmpty(text)) return;
            float e = Sc;
            string hotkey = null, rest = text;
            if (text.StartsWith("[") && text.IndexOf(']') > 1)
            {
                int i = text.IndexOf(']');
                hotkey = text.Substring(1, i - 1);
                rest = text.Substring(i + 1).Trim();
            }
            float tw = Width(rest, 22f, false);
            float kw = hotkey != null ? Mathf.Max(34f * e, Width(hotkey, 18f, true) + 20f * e) + 10f * e : 0f;
            float w = tw + kw + 56f * e;
            Rect r = new Rect((W - w) * 0.5f, y, w, 46f * e);
            Box(new Rect(r.x - 3f * e, r.y, r.width + 6f * e, r.height + 8f * e), new Color(0f, 0f, 0f, 0.28f), 26f * e);
            Box(r, Backdrop, 23f * e);
            float x = r.x + 18f * e;
            if (hotkey != null)
            {
                Rect k = new Rect(x, r.y + 8f * e, kw - 10f * e, 30f * e);
                Box(k, new Color(0.26f, 0.29f, 0.34f), 8f * e);
                Text(k, hotkey, 18f, White, TextAnchor.MiddleCenter, true);
                x += kw;
            }
            else
            {
                Box(new Rect(x, r.y + r.height * 0.5f - 5f * e, 10f * e, 10f * e), point, 5f * e);
                x += 22f * e;
            }
            Text(new Rect(x, r.y, tw + 8f, r.height), rest, 22f, White, TextAnchor.MiddleLeft, false);
        }

        /// <summary>Instruction box for the dashboard adjustment mode.</summary>
        public static void Calibration(float W, float H, string text)
        {
            float e = Sc;
            Rect r = new Rect(W * 0.5f - 480f * e, H * 0.05f, 960f * e, 100f * e);
            Box(new Rect(r.x - 6f * e, r.y, r.width + 12f * e, r.height + 12f * e), new Color(0f, 0f, 0f, 0.30f), 22f * e);
            Box(r, Backdrop, 18f * e);
            Box(new Rect(r.x + 18f * e, r.y, 64f * e, 5f * e), Yellow, 3f * e);
            Text(new Rect(r.x + 20f * e, r.y + 8f * e, r.width - 40f * e, r.height - 12f * e), text, 21f, Yellow, TextAnchor.MiddleCenter, false);
        }
    }
}
